//! Visual representation of bloater toxic clouds: 6-10 slowly drifting, fading `toxic_puff` props.

use glam::{Mat4, Quat, Vec3};

/// Prop model name generated by R32-09 (`assets/models/props/toxic_puff.glb`). // new: DECISIONS 2026-11-25
pub const PROP_NAME: &str = "toxic_puff";
/// Maximum simultaneous clouds rendered; oldest is replaced when exceeded. // new: DECISIONS 2026-11-25
pub const MAX_CLOUDS: usize = 3;
/// Minimum puffs per cloud. // new: DECISIONS 2026-11-25
pub const PUFFS_MIN: usize = 6;
/// Maximum puffs per cloud. // new: DECISIONS 2026-11-25
pub const PUFFS_MAX: usize = 10;
/// Minimum initial uniform scale of a puff prop. // new: DECISIONS 2026-11-25
pub const SCALE_MIN: f32 = 1.5;
/// Maximum initial uniform scale of a puff prop. // new: DECISIONS 2026-11-25
pub const SCALE_MAX: f32 = 3.0;
/// Duration at the end of a cloud's life over which puffs scale down to zero. // new: DECISIONS 2026-11-25
pub const FADE_OUT_SECONDS: f32 = 1.5;
/// Slow outward horizontal drift speed in m/s. // new: DECISIONS 2026-11-25
const DRIFT_SPEED: f32 = 0.25;
/// Gentle upward float speed in m/s. // new: DECISIONS 2026-11-25
const RISE_SPEED: f32 = 0.12;
/// Slow puff rotation speed in rad/s. // new: DECISIONS 2026-11-25
const YAW_SPIN: f32 = 0.25;

/// World-space transform for one rendered `toxic_puff` prop instance.
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct PuffInstance {
    pub position: Vec3,
    pub yaw: f32,
    pub scale: f32,
}

impl PuffInstance {
    /// Model matrix combining uniform scale, Y rotation and world translation.
    pub fn matrix(&self) -> Mat4 {
        Mat4::from_scale_rotation_translation(
            Vec3::splat(self.scale),
            Quat::from_rotation_y(self.yaw),
            self.position,
        )
    }
}

struct Puff {
    offset: Vec3,
    drift: Vec3,
    base_scale: f32,
    yaw: f32,
    spin: f32,
}

struct Cloud {
    origin: Vec3,
    age: f32,
    duration: f32,
    puffs: Vec<Puff>,
}

/// Manages active visual toxic clouds and emits `toxic_puff` prop instances each frame.
pub struct ToxicCloudView {
    clouds: Vec<Cloud>,
    rng: u64,
}

impl Default for ToxicCloudView {
    fn default() -> Self {
        Self::new()
    }
}

impl ToxicCloudView {
    pub fn new() -> Self {
        Self {
            clouds: Vec::with_capacity(MAX_CLOUDS),
            rng: 0x9E37_79B9_7F4A_7C15,
        }
    }

    fn next_f32(&mut self) -> f32 {
        self.rng ^= self.rng << 13;
        self.rng ^= self.rng >> 7;
        self.rng ^= self.rng << 17;
        (self.rng >> 40) as f32 / (1u64 << 24) as f32
    }

    /// Spawns a new visual toxic cloud at `origin` with `radius` and `duration`.
    /// Keeps at most `MAX_CLOUDS` active, replacing the oldest when full.
    pub fn spawn(&mut self, origin: Vec3, radius: f32, duration: f32) {
        if duration <= 0.0 {
            return;
        }
        if self.clouds.len() >= MAX_CLOUDS {
            self.clouds.remove(0);
        }
        let span = PUFFS_MAX - PUFFS_MIN + 1;
        let count = PUFFS_MIN + ((self.next_f32() * span as f32) as usize).min(span - 1);
        let spread = (radius * 0.7).max(0.5);
        let mut puffs = Vec::with_capacity(count);
        for i in 0..count {
            let base_angle = std::f32::consts::TAU * i as f32 / count as f32;
            let angle = base_angle + (self.next_f32() - 0.5) * 0.6;
            let dist = spread * (0.2 + 0.8 * self.next_f32());
            let dir_x = angle.cos();
            let dir_z = angle.sin();
            let height = 0.3 + 0.8 * self.next_f32();
            let base_scale = SCALE_MIN + (SCALE_MAX - SCALE_MIN) * self.next_f32();
            let yaw = self.next_f32() * std::f32::consts::TAU;
            let spin = if self.next_f32() < 0.5 { -YAW_SPIN } else { YAW_SPIN };
            let drift_mag = DRIFT_SPEED * (0.6 + 0.8 * self.next_f32());
            let rise = RISE_SPEED * (0.5 + self.next_f32());
            puffs.push(Puff {
                offset: Vec3::new(dir_x * dist, height, dir_z * dist),
                drift: Vec3::new(dir_x * drift_mag, rise, dir_z * drift_mag),
                base_scale,
                yaw,
                spin,
            });
        }
        self.clouds.push(Cloud {
            origin,
            age: 0.0,
            duration,
            puffs,
        });
    }

    /// Advances all clouds by `dt` seconds and drops expired ones.
    pub fn update(&mut self, dt: f32) {
        if dt <= 0.0 {
            return;
        }
        for cloud in &mut self.clouds {
            cloud.age += dt;
        }
        self.clouds.retain(|c| c.age < c.duration);
    }

    /// Fills `out` with the current frame's `toxic_puff` prop instances.
    pub fn fill_instances(&self, out: &mut Vec<PuffInstance>) {
        out.clear();
        for cloud in &self.clouds {
            let remaining = (cloud.duration - cloud.age).max(0.0);
            let fade_window = FADE_OUT_SECONDS.min(cloud.duration);
            let fade = if fade_window <= 0.0 {
                0.0
            } else {
                (remaining / fade_window).clamp(0.0, 1.0)
            };
            for puff in &cloud.puffs {
                let scale = puff.base_scale * fade;
                if scale <= 0.01 {
                    continue;
                }
                out.push(PuffInstance {
                    position: cloud.origin + puff.offset + puff.drift * cloud.age,
                    yaw: puff.yaw + puff.spin * cloud.age,
                    scale,
                });
            }
        }
    }

    /// Convenience helper returning a fresh vector of active puff instances.
    pub fn instances(&self) -> Vec<PuffInstance> {
        let mut out = Vec::new();
        self.fill_instances(&mut out);
        out
    }

    /// Number of currently active clouds (at most `MAX_CLOUDS`).
    pub fn cloud_count(&self) -> usize {
        self.clouds.len()
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn spawns_6_to_10_puffs_within_scale_bounds() {
        let mut view = ToxicCloudView::new();
        view.spawn(Vec3::new(10.0, 0.0, -5.0), 4.0, 6.0);
        assert_eq!(view.cloud_count(), 1);
        let puffs = view.instances();
        assert!((PUFFS_MIN..=PUFFS_MAX).contains(&puffs.len()));
        for p in &puffs {
            assert!(p.scale >= SCALE_MIN && p.scale <= SCALE_MAX);
        }
    }

    #[test]
    fn puffs_drift_and_fade_over_last_1_5_seconds() {
        let mut view = ToxicCloudView::new();
        view.spawn(Vec3::ZERO, 4.0, 6.0);
        let start = view.instances();

        view.update(2.0);
        let mid = view.instances();
        assert_eq!(start.len(), mid.len());
        // Still outside the last 1.5 s fade window: scale unchanged, position drifted.
        assert!((mid[0].scale - start[0].scale).abs() < 1e-4);
        assert!(mid[0].position.distance(start[0].position) > 0.1);

        // Advance to 5.25 s (0.75 s remaining -> half of 1.5 s fade window).
        view.update(3.25);
        let fading = view.instances();
        assert!((fading[0].scale - start[0].scale * 0.5).abs() < 1e-3);

        // Past duration -> removed.
        view.update(1.0);
        assert_eq!(view.cloud_count(), 0);
        assert!(view.instances().is_empty());
    }

    #[test]
    fn caps_at_3_clouds_replacing_oldest() {
        let mut view = ToxicCloudView::new();
        view.spawn(Vec3::new(0.0, 0.0, 0.0), 4.0, 6.0);
        view.update(1.0);
        view.spawn(Vec3::new(20.0, 0.0, 0.0), 4.0, 6.0);
        view.spawn(Vec3::new(40.0, 0.0, 0.0), 4.0, 6.0);
        assert_eq!(view.cloud_count(), MAX_CLOUDS);

        // Fourth cloud replaces the oldest (the one at x = 0).
        view.spawn(Vec3::new(60.0, 0.0, 0.0), 4.0, 6.0);
        assert_eq!(view.cloud_count(), MAX_CLOUDS);
        let puffs = view.instances();
        assert!(puffs.iter().all(|p| p.position.x > 10.0));
    }
}
